'use strict';
// Execute the real scene factory and its registered motion callbacks, not a
// reconstructed controller. Simulation time excludes the core's hidden pause
// and intentional .06 s per-frame cap; those policies are tested separately.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),cp=require('./portable-baseline.cjs'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..'),baseline='4292d844656475f80ddf1bfde02c857976bee866';
const code=process.argv.includes('--baseline')?cp.execFileSync('git',['show',baseline+':dist/scenes/elevator.js'],{cwd:root,encoding:'utf8'}):fs.readFileSync(path.join(root,'dist/scenes/elevator.js'),'utf8');
function make(source=code){const ctx={window:{},URLSearchParams,addEventListener(){}};vm.createContext(ctx);vm.runInContext(fs.readFileSync(path.join(root,'dist/core.js'),'utf8'),ctx);vm.runInContext(source,ctx);const cfg=ctx.window.SCENES.elevator(),steps=new Set(),messages=[];const ui={animate:f=>steps.add(f),flash:t=>messages.push(t),invalidate(){}};
 const f={cfg,s:cfg.state,steps,messages,ui,frame(dt){for(const step of [...steps])if(step(dt)===false)steps.delete(step);},act(label){cfg.buttons.find(b=>b.label===label).onClick(cfg.state,ui);},tick(t,dt){while(t>1e-12){const take=Math.min(dt,t);this.frame(take);t-=take;}},snapshot(){return JSON.parse(JSON.stringify(this.s));}};return f;}
const tests=[],near=(a,b,label,eps=2e-9)=>assert(Math.abs(a-b)<=eps,`${label}: ${a} vs ${b}`);
function test(name,fn){try{fn();tests.push({name,ok:true});}catch(e){tests.push({name,ok:false,error:e.message});}}
function compare(a,b){for(const k of ['pos','door','timer'])near(a.s[k],b.s[k],k);for(const k of ['floor','target','phase','trips'])assert.equal(a.s[k],b.s[k],k);assert.deepEqual([...a.s.queue],[...b.s.queue]);}
function invariant(f){const s=f.s;assert(s.pos>=0&&s.pos<=66);assert(s.door>=0&&s.door<=1);if(s.phase==='moving')assert.equal(s.door,0);else near(s.pos,(s.floor-1)*33,'level');assert(f.steps.size<=2);}
const timeline=[[0,'前往三楼'],[.31,'开门'],[.52,'关门'],[.70,'前往二楼'],[1.15,'前往三楼'],[2.20,'开门'],[4.40,'前往一楼'],[8.10,'开门'],[8.25,'关门']];
function replay(dt){const f=make(),samples=[];let time=0;const checkpoints=[...new Set([...timeline.map(x=>x[0]),.85,1,2,3,5.75,6.60,8,9,12,16,20,30])].sort((a,b)=>a-b);for(const target of checkpoints){f.tick(target-time,dt);time=target;for(const[t,act]of timeline)if(t===target)f.act(act);invariant(f);samples.push({time,state:f.snapshot()});}return{f,samples};}
const startup={};for(const hz of [20,30,60,120]){const f=make();f.act('前往三楼');f.tick(1,1/hz);startup[hz]={position:f.s.pos,door:f.s.door,phase:f.s.phase,timer:f.s.timer};}
test('Same timed inputs have equal state at20/30/60/120Hz and irregular partitions',()=>{const gold=replay(1/120);for(const dt of [1/20,1/30,1/60,.173]){const run=replay(dt);for(let i=0;i<gold.samples.length;i++){const a={s:run.samples[i].state},b={s:gold.samples[i].state};compare(a,b);}assert.equal(run.f.steps.size,0);}});
test('Exact phase boundaries consume remainder; a single step can finish queued trips',()=>{const f=make();f.act('前往三楼');f.frame(.85);assert.equal(f.s.phase,'moving');near(f.s.timer,0,'moving timer');near(f.s.door,0,'door');f.frame(4.9);assert.equal(f.s.phase,'opening');near(f.s.pos,66,'arrival');assert.equal(f.s.trips,1);f.frame(.85);assert.equal(f.s.phase,'waiting');f.frame(1.4);assert.equal(f.s.phase,'idle');assert.equal(f.steps.size,0);const a=make(),b=make();for(const x of [a,b]){x.act('前往三楼');x.act('前往二楼');x.act('前往三楼');}a.frame(30);b.tick(30,1/120);compare(a,b);assert.equal(a.s.trips,2);assert.equal(a.steps.size,0);});
test('Mid-door reversals and repeated floor calls retain destination exactly once',()=>{for(const hz of [20,30,60,120]){const f=make();f.act('前往三楼');f.tick(.3,1/hz);const d=f.s.door;f.act('开门');near(f.s.door,d,'reversal pose');f.act('开门');assert.deepEqual([...f.s.queue],[3]);f.tick(.11,1/hz);assert(f.s.door>d);f.act('关门');f.act('前往二楼');f.act('前往二楼');f.tick(30,1/hz);assert.equal(f.s.floor,2);assert.equal(f.s.trips,2);assert.equal(f.steps.size,0);}});
test('Reset invalidates stale callbacks and never reuses the previous frame remainder',()=>{for(const at of [.2,1,5.9,6.8]){const f=make();f.act('前往三楼');f.tick(at,1/30);const stale=[...f.steps];f.act('回到一楼');const state=f.snapshot();for(const cb of stale)assert.equal(cb(30),false);assert.deepEqual(f.snapshot(),state);f.frame(30);assert.equal(f.steps.size,0);f.act('前往二楼');f.frame(.2);assert.equal(f.s.trips,0);near(f.s.door,1-.2/.85,'fresh door');}});
test('Zero, negative and nonfinite deltas cannot alter state',()=>{const f=make();f.act('前往三楼');const s=f.snapshot();for(const dt of [0,-.1,NaN,Infinity,-Infinity]){f.frame(dt);assert.deepEqual(f.snapshot(),s);}f.frame(.1);invariant(f);});
test('Read/exit/reenter observation does not edit motion or insert controller ticks',()=>{const a=make(),b=make();for(const f of [a,b])f.act('前往三楼');for(let i=0;i<200;i++){a.cfg.lesson.onToggle(a.s,!!(i%2),a.ui);a.cfg.lesson.read(a.s);a.frame(.04);b.frame(.04);compare(a,b);}assert.equal(a.s.trips,1);});
test('Production RAF retains .06 cap, hidden suspension, slow rate and idle parking',()=>{
 const fixture=require('./review-process-invariants.cjs').fixture;
 const a=fixture('elevator'),b=fixture('elevator');a.button('前往三楼');b.button('前往三楼');a.frame(10);b.frame(.06);compare(a,b);
 const held=a.snapshot();a.document.hidden=true;a.document.emit('visibilitychange');a.tick(50);assert.equal(a.snapshot(),held);assert.equal(a.pending,0);a.document.hidden=false;a.document.emit('visibilitychange');a.frame(.04);b.frame(.04);compare(a,b);
 const fast=fixture('elevator'),slow=fixture('elevator');fast.button('前往三楼');slow.button('前往三楼');slow.ui.simulationRate=.25;for(let i=0;i<80;i++){fast.frame(.04);for(let j=0;j<4;j++)slow.frame(.04);}compare(fast,slow);
 a.finish();b.finish();assert.equal(a.s.trips,1);assert.equal(a.pending,0);const frames=a.frames;a.tick(10);assert.equal(a.frames,frames);
});
test('A completed driver cannot revive when a later trip starts',()=>{const f=make();f.act('前往三楼');const old=[...f.steps].at(-1);f.frame(30);f.act('前往一楼');const s=f.snapshot();assert.equal(old(5),false);assert.deepEqual(f.snapshot(),s);f.frame(.2);near(f.s.door,1-.2/.85,'new trip only');});
const report={baseline,mode:process.argv.includes('--baseline')?'baseline':'candidate',tolerance:2e-9,scope:'Real elevator factory callbacks; core cap/visibility policy unchanged; not browser FPS/audio audition',startup,passed:tests.filter(x=>x.ok).length,total:tests.length,tests};
console.log(JSON.stringify(report,null,2));if(process.env.ELEVATOR_TIME_REPORT)fs.writeFileSync(process.env.ELEVATOR_TIME_REPORT,JSON.stringify(report,null,2)+'\n');if(report.passed!==report.total)process.exitCode=1;
module.exports={make,replay};
